<script setup>
import { ref,computed,onMounted,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import { api,send,money } from '../api';
const route=useRoute(),router=useRouter(),shop=ref(null),service=ref(null),daysOff=ref([]),packages=ref([]),selectedPackage=ref(''),error=ref(''),busy=ref(false);const shopDay=(offset=0)=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(Date.now()+offset*86400000));const initial=shopDay(1);const form=ref({preferred_date:initial,preferred_time:'10:00',contact_name:'',contact_phone:'',note:'',consent:false,website:''});const times=Array.from({length:24},(_,i)=>String(9+Math.floor(i/2)).padStart(2,'0')+':'+(i%2?'30':'00'));const maxDate=shopDay(180);const unavailable=computed(()=>daysOff.value.includes(form.value.preferred_date));const chosen=computed(()=>packages.value.find(p=>p.id===selectedPackage.value));const slots=ref([]),slotLoading=ref(false);const offeredTimes=computed(()=>times.filter(t=>slots.value.includes(t)));let availabilityVersion=0;async function loadAvailability(){if(!form.value.preferred_date||!service.value||!selectedPackage.value)return;const requestVersion=++availabilityVersion;slotLoading.value=true;error.value='';try{const r=await api(`/public/shops/${route.params.slug}/availability?`+new URLSearchParams({date:form.value.preferred_date,service_id:service.value.id,package_id:selectedPackage.value}));if(requestVersion!==availabilityVersion)return;slots.value=r.available_slots||[]; if(!offeredTimes.value.includes(form.value.preferred_time))form.value.preferred_time=offeredTimes.value[0]||'';}catch(e){if(requestVersion===availabilityVersion)error.value=e.message;}finally{if(requestVersion===availabilityVersion)slotLoading.value=false}}watch(()=>[form.value.preferred_date,selectedPackage.value],loadAvailability);
onMounted(async()=>{try{const slug=route.params.slug;const [m,s,d]=await Promise.all([api('/public/shops/'+slug),api('/public/shops/'+slug+'/services'),api('/public/shops/'+slug+'/days-off')]);shop.value=m.merchant;service.value=s.items.find(x=>x.id===route.params.serviceId);daysOff.value=d.dates;if(!service.value)throw Error('服务不存在或已下架');packages.value=(await api('/public/shops/'+slug+'/packages?service_id='+service.value.id)).items;selectedPackage.value=packages.value[0]?.id||'';if(!selectedPackage.value)throw Error('该服务暂无可预约套餐');await loadAvailability()}catch(e){error.value=e.message}});
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{if(unavailable.value||!form.value.preferred_time||!offeredTimes.value.includes(form.value.preferred_time))throw Error('请选择一个尚未被确认占用的时段');const key=crypto.randomUUID().replaceAll('-','');const payload={...form.value,service_id:service.value.id,package_id:selectedPackage.value};const result=await send(`/public/shops/${route.params.slug}/bookings`,payload,'POST',{'Idempotency-Key':key});sessionStorage.setItem('last-booking',JSON.stringify({code:result.code,title:service.value.title+' · '+chosen.value.title,date:form.value.preferred_date,time:form.value.preferred_time,status:'pending'}));router.replace({path:`/s/${route.params.slug}/success`,query:{code:result.code}})}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="light-page"><header class="simple-header wrap"><router-link :to="`/s/${route.params.slug}`">← 返回工作室</router-link><span class="brand">◈ 约客助手</span></header><main class="booking-layout wrap" v-if="shop&&service"><section class="form-area"><div class="eyebrow dark">BOOK YOUR EXPERIENCE</div><h1>预约你的专属时光<span class="dot">.</span></h1><p class="muted">填写拍摄意向，工作室核对档期后将与你联系。</p><form @submit.prevent="submit"><div class="form-section"><div class="form-section-heading"><b>01</b><h3>选择拍摄套餐与时间</h3></div><label>拍摄套餐<select v-model="selectedPackage" required><option v-for="p in packages" :key="p.id" :value="p.id">{{p.title}} · {{money(p.price_cents)}} · {{p.duration_minutes}}分钟</option></select></label><p v-if="chosen" class="hint">{{chosen.description}} · 准备{{chosen.buffer_before}}分钟 / 收尾{{chosen.buffer_after}}分钟</p><label>心仪日期<input v-model="form.preferred_date" type="date" :min="initial" :max="maxDate" required/></label><div v-if="unavailable" class="alert">该日期工作室暂停接单，请更换日期</div><label>偏好时段<select v-model="form.preferred_time"><option v-for="t in offeredTimes" :key="t" :value="t">{{t}}</option></select></label><small class="hint">已确认预约的时段会自动隐藏。{{slotLoading?'正在检查档期…':offeredTimes.length?'提交仍是意向申请，需商家确认。':'当天暂无可选时段，请更换日期。'}}</small></div><div class="form-section"><div class="form-section-heading"><b>02</b><h3>留下联系方式</h3></div><div class="form-grid"><label>怎么称呼你<input v-model.trim="form.contact_name" maxlength="40" autocomplete="name" placeholder="例如：陈女士" required/></label><label>联系电话<input v-model.trim="form.contact_phone" maxlength="25" inputmode="tel" autocomplete="tel" placeholder="商家确认预约时联系" required/></label></div><label>其他拍摄想法（选填）<textarea v-model="form.note" maxlength="500" rows="4" placeholder="如拍摄人数、风格偏好或其他需求"></textarea></label><input v-model="form.website" style="position:absolute;left:-9999px" tabindex="-1" autocomplete="off" aria-hidden="true"/><label class="consent"><input v-model="form.consent" type="checkbox" required/><span>我同意提供以上信息给该工作室用于联系和处理本次预约。数据仅用于预约服务，请勿填写身份证号或其他敏感资料。</span></label></div><div v-if="error" class="alert">{{error}}</div><button type="submit" class="button primary big" :disabled="busy||unavailable||slotLoading||!offeredTimes.length">{{busy?'正在提交…':'提交预约申请'}} <span>↗</span></button></form></section><aside class="order-summary"><div class="summary-art">YOUR<br/><em>MOMENT.</em></div><div class="summary-content"><div class="eyebrow dark">YOUR SELECTION</div><h2>{{service.title}}</h2><p>{{service.description}}</p><div class="summary-line"><span>参考价格</span><strong>{{money(chosen?.price_cents??service.price_cents)}}</strong></div><div class="summary-line"><span>预计时长</span><strong>{{chosen?.duration_minutes??service.duration_minutes}} 分钟</strong></div><div class="summary-disclaimer">预约申请免费提交，具体价格与服务以商家确认为准。</div></div></aside></main><div v-else class="center-state">{{error||'加载中…'}}</div></div></template>
